import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import { getComments, getPost, getPosts } from '@/lib/posts'

// Revalidated at most once every 5 minutes (ISR).
export const revalidate = 300

// Ids that `generateStaticParams` did not return are rendered on demand and
// then cached. This replaces `fallback: 'blocking'` from `getStaticPaths`.
export const dynamicParams = true

type BlogPostProps = {
  params: Promise<{ id: string }>
}

export async function generateStaticParams() {
  const posts = await getPosts()

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: BlogPostProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    return {
