  font-size: 16px;
}

button:hover {
  background: #0051a2;
}

import type { NextRequest } from 'next/server'
import type { ApiPost } from '../types'

// Methods that are not exported here (POST, PATCH, ...) are answered by
// Next.js with a 405 and the appropriate `Allow` header.

type RouteParams = {
  params: Promise<{ id: string }>
}

export async function GET(request: NextRequest, { params }: RouteParams) {
  const { id } = await params

  // Simulate fetching a single post
  const post: ApiPost = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(request: NextRequest, { params }: RouteParams) {
  const { id } = await params

  // Every field is optional for this simulated update, so an empty or
  // unparseable body is treated as "no changes".
  let body: Partial<ApiPost> = {}

  try {
    body = (await request.json()) as Partial<ApiPost>
  } catch {
    body = {}
  }

  const { title, content } = body

  // Simulate updating a post
  const updatedPost: ApiPost = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(request: NextRequest, { params }: RouteParams) {
  const { id } = await params

  // Simulate deleting a post
  return Response.json({ message: `Post ${id} deleted successfully` })
}

import type { NextRequest } from 'next/server'
import type { ApiPost } from './types'

// Methods that are not exported here (PUT, DELETE, ...) are answered by
// Next.js with a 405 and the appropriate `Allow` header.

export async function GET() {
  // Simulate fetching posts
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return Response.json(posts)
}

export async function POST(request: NextRequest) {
  let body: Partial<ApiPost>

  try {
    body = (await request.json()) as Partial<ApiPost>
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const { title, content } = body

  if (!title || !content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  // Simulate creating a post
  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}

'use client' // Error boundaries must be Client Components

import { useEffect } from 'react'

export default function Error({
  error,
  retry,
}: {
  error: Error & { digest?: string }
  retry: () => void
}) {
  useEffect(() => {
    // Log the error to an error reporting service
    console.error(error)
  }, [error])

  return (
    <div className="error-page">
      <title>Error - My Blog</title>

      <h1>An error occurred</h1>
      <p>Sorry, something went wrong.</p>
      <button onClick={() => retry()}>Try again</button>
    </div>
  )
}

